using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    public void wave_action(Control o,string operation)
    {
        var actor=Document(o).Call("actor_for_clip",o.Get("_wave_clip_id")).AsGodotObject();if(actor==null){notice(o,"Double-click a clip to open its waveform first.");return;}var waveform=Field<Control>(o,"waveform");var selection=waveform.Get("selection").AsVector2I();if(selection.Y<=selection.X&&operation!="paste")return;if(waveform.Get("channel").AsInt32()>=0&&operation is "cut" or "paste" or "trim" or "time_stretch"){notice(o,"Choose Stereo for duration-changing edits so both channels stay aligned. Pitch, gain, fades, silence, reverse and repair can edit one channel independently.");return;}if(operation is "time_stretch" or "pitch_shift"){bool stretch=operation=="time_stretch";var dialog=window(o,operation.Capitalize().Replace("_"," ")+" selection",new Vector2I(420,210));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();double amount=stretch?1.25:0;NumberAction(o,host,stretch?"Duration ratio":"Semitones",amount,stretch?.25:-24,stretch?4:24,stretch?.01:.1,value=>amount=value);label(host,"Processes only the selected samples and preserves the untouched audio as adjacent source clips. Undo restores the original clip. Time stretching changes only this clip's length.");ActionButton(host,"Apply",()=>{perform_wave_edit(o,operation,amount);windowNode.QueueFree();});return;}if(operation is "amplify" or "normalize"){var dialog=window(o,operation.Capitalize()+" selection",new Vector2I(380,170));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();double amount=operation=="amplify"?3:-1;NumberAction(o,host,"dB",amount,-60,24,.1,value=>amount=value);ActionButton(host,"Apply",()=>{perform_wave_edit(o,operation,amount);windowNode.QueueFree();});return;}perform_wave_edit(o,operation,0);
    }
    public void perform_wave_edit(Control o,string operation,double amount)
    {
        string id=o.Get("_wave_clip_id").AsString();if(!Session(o).Call("can_edit",id).AsBool()){notice(o,"The clip's track is locked or unavailable.");return;}var actor=Document(o).Call("actor_for_clip",id).AsGodotObject();var clip=Document(o).Call("clip_for_id",id).AsGodotObject();if(actor==null||clip==null)return;finish_control_edits(o);Session(o).Call("commit");var source=workspace_source(Get(Dict(actor,"values"),"audio"));if(source==null){notice(o,"The selected audio source is missing.");return;}using var regions=new AudioRegionEditOperations();string error=regions.unsupported_reason(clip,actor,operation);if(error.Length>0){notice(o,error);return;}var capturedClip=((Resource)clip).Duplicate(false);var capturedActor=new ActorData();capturedActor.Set("id",actor.Get("id"));capturedActor.Set("type_id",actor.Get("type_id"));capturedActor.Set("values",Dict(actor,"values").Duplicate(true));foreach(var animation in Items(actor,"animation_tracks"))Items(capturedActor,"animation_tracks").Add(animation.AsGodotObject().Call("copy_track"));var waveform=Field<Control>(o,"waveform");int rate=waveform.Get("rate").AsInt32(),channel=waveform.Get("channel").AsInt32(),clipboardRate=o.Get("_wave_clipboard_rate").AsInt32();var selection=waveform.Get("selection").AsVector2I();var clipboard=o.Get("_wave_clipboard").AsVector2Array();long ownerId=unchecked((long)Session(o).GetInstanceId());Work(o,"wave_edit",Session(o).Get("revision").AsInt64(),job=>{using var worker=new AudioRegionEditOperations();var result=worker.prepare(capturedClip,capturedActor,source,operation,selection,rate,amount,channel,clipboard,clipboardRate,job);result["owner_id"]=ownerId;return result;});
    }
    public void set_sample_value_dialog(Control o)
    {
        var waveform=Field<Control>(o,"waveform");if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()||waveform.Get("stream").AsGodotObject()==null){notice(o,"Open a waveform and finish recording first.");return;}var owner=Session(o);var document=Document(o);long revision=owner.Get("revision").AsInt64();string id=o.Get("_wave_clip_id").AsString();var frames=waveform.Get("selection").AsVector2I();if(frames.Y<=frames.X)frames.Y=frames.X+1;int channel=waveform.Get("channel").AsInt32();double amount=0;var dialog=window(o,"Set sample amplitude",new Vector2I(460,230));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();label(host,"Set source frames "+frames.X+"–"+frames.Y+" on "+(channel<0?"both channels":channel==0?"left":"right")+". This writes an exact constant value, not a gain adjustment. Untouched source regions remain shared; the edit is undoable.");NumberAction(o,host,"Amplitude",0,-1,1,.0001,value=>amount=value);ActionButton(host,"Apply sample value",()=>{if(Session(o)!=owner||Document(o)!=document||owner.Get("revision").AsInt64()!=revision||o.Get("_wave_clip_id").AsString()!=id||Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()){notice(o,"The waveform owner changed. Reopen Set sample value.");return;}waveform.Set("selection",frames);waveform.Set("channel",channel);perform_wave_edit(o,"set_amplitude",amount);windowNode.QueueFree();});
    }
    public void export_timeline_midi(Control o)
    {
        var owner=Session(o);long revision=owner.Get("revision").AsInt64();var dialog=window(o,"Export timeline notes as MIDI",new Vector2I(690,380));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();label(host,"This separate note-only export maps editable notes through timeline placement, source trims, speed, reverse and clip loops into the project conductor. Enabled sustain, step swing/probability/accent/ratchets are projected; raw controllers are omitted. Clipped held notes retrigger at the window edge. Whole-semitone static clip pitch is supported; pitch automation and frozen note tracks are refused.");label(host,"Audio clips, sample/voice/envelope behavior, effects, fades, mix gain/pan, other automation and routing/sends are not encoded. Direct clip/track mute and routing-aware solo select included notes. MIDI programs are approximations. Up to 15 melodic track/program parts plus shared channel-10 percussion; output is 480 PPQ. Source-pattern export remains available separately.");ActionButton(host,"Prepare timeline notes MIDI",()=>{windowNode.QueueFree();if(Session(o)!=owner||owner.Get("revision").AsInt64()!=revision){notice(o,"The composition changed. Open timeline MIDI export again.");return;}using var midi=new AudioMidiTimelineOperations();string error=midi.preflight((RefCounted)Document(o));if(error.Length>0){notice(o,error);return;}var snapshot=Document(o).Call("snapshot").As<RefCounted>();Work(o,"timeline_midi",revision,job=>{using var worker=new AudioMidiTimelineOperations();return new Settings{["midi"]=worker.build(snapshot,job),["owner_session"]=owner,["revision"]=revision};});});
    }
    public void complete_midi_export(Control o,Settings context,Settings target,Settings midi,bool timeline)
    {
        if(Session(o)!=context["session"].AsGodotObject()||Session(o).Get("revision").AsInt64()!=context["revision"].AsInt64()){notice(o,"The composition changed while choosing a file. Repeat this action in the intended document.");return;}if(target.Count==0)return;using var writer=new AudioMidiOperations();var error=writer.write(Get(target,"path","").AsString(),midi["parts"].AsGodotArray(),midi["tempos"],midi["meters"]);Field<Label>(o,"status").Text=error==Error.Ok?timeline?"Timeline note placements and conductor saved. Audio processing/routing and raw controllers are excluded.":"MIDI source notes saved. Project conductor, clip placement, trims, speed and loops are not included.":error==Error.AlreadyExists?"MIDI destination already exists; choose a new filename. Existing contents were preserved.":"MIDI could not be saved: "+error;
    }
}
